// Inputs: the Extract output (items, delivery_date, area) and Price_List rows.
// "Run once for all items" mode has no .item; each run handles one message,
// so .first() is that message. (In "each item" mode, use $('Extract').item.)
const ex = $('Extract').first().json.output;
const products = $('Price_List').all().map(i => i.json).filter(p => p.active !== 'no');
const find = w => {
  const s = String(w ?? '').toLowerCase().trim();
  const hits = products.filter(p =>
    String(p.aliases).toLowerCase().split(',').map(a => a.trim()).some(a => a && s.includes(a)));
  return hits.length === 1 ? hits[0] : null;            // 0 or 2+ matches → ask
};
const lines = [], ask = [], human = [];
for (const it of ex.items ?? []) {
  const p = find(it.product), qty = Number(it.qty);
  if (!p) { ask.push(`Which product do you mean by "${it.product}"?`); continue; }
  if (!Number.isInteger(qty) || qty <= 0) { ask.push(`How many ${p.unit}s of ${p.name}?`); continue; }
  if (qty > 50) { human.push(`${qty} × ${p.name}`); continue; }
  if (qty > Number(p.stock)) { ask.push(`Only ${p.stock} ${p.unit}(s) of ${p.name} left. Shall we send ${p.stock}?`); continue; }
  lines.push({ sku: p.sku, name: p.name, unit: p.unit, qty, price: Number(p.price), line_total: qty * Number(p.price) });
}
if (!ex.delivery_date) ask.push('Which day should we deliver?');
if (!ex.area) ask.push('Which area should we deliver to?');
const subtotal = lines.reduce((s, l) => s + l.line_total, 0);
const delivery_fee = subtotal >= 30000 ? 0 : 1500;
const total = subtotal + delivery_fee;
if (total > 500000) human.push('order above ₦500,000');
const route = human.length ? 'tolu' : ask.length || !lines.length ? 'ask' : 'ready';
return [{ json: { route, lines, ask, human, subtotal, delivery_fee, total,
                  delivery_date: ex.delivery_date, area: ex.area } }];
